-- src/db/sqlite.js init() on an empty DATA_DIR (migrations 1 and 2), then one INSERT per table
-- (users, push_tokens, audit_log, refresh_tokens). The user password_hash is a bcrypt hash of the
-- string "fixture". Dumped with a small better-sqlite3 script (sqlite_master + INSERTs) because
-- the sqlite3 CLI is not installed.
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE schema_migrations (
      version INTEGER PRIMARY KEY,
      description TEXT,
      applied_at DATETIME DEFAULT (datetime('now'))
    );
CREATE TABLE users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        email TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'viewer' CHECK(role IN ('admin', 'operator', 'viewer')),
        created_at DATETIME DEFAULT (datetime('now')),
        last_login DATETIME
      );
CREATE TABLE push_tokens (
        token TEXT PRIMARY KEY,
        user_id TEXT,
        server_name TEXT,
        created_at DATETIME DEFAULT (datetime('now')),
        updated_at DATETIME DEFAULT (datetime('now'))
      );
CREATE TABLE audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT,
        action TEXT NOT NULL,
        target TEXT,
        detail TEXT,
        created_at DATETIME DEFAULT (datetime('now'))
      );
CREATE TABLE refresh_tokens (
        hash TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        role TEXT NOT NULL,
        fingerprint TEXT,
        expires_at INTEGER NOT NULL,
        created_at INTEGER NOT NULL DEFAULT (unixepoch())
      );
CREATE INDEX idx_audit_created ON audit_log(created_at);
CREATE INDEX idx_refresh_expires ON refresh_tokens(expires_at);
